    <script src="https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.page.js" defer></script>
    <script>
      window.OneSignalDeferred = window.OneSignalDeferred || [];
      OneSignalDeferred.push(async function(OneSignal) {
        try {
          await OneSignal.init({
            appId: "94fc5c63-540e-479f-8866-ecc43fc7915c",
          });
          console.log("OneSignal inicializado com sucesso.");
        } catch (e) {
          console.error("Erro no OneSignal init:", e);
        }
      });
    </script>
    <script type="module" crossorigin src="/assets/index-D-ckaPHJ.js"></script>
    <link rel="stylesheet" crossorigin href="/assets/index-DQizOmHm.css">
  <link rel="manifest" href="/manifest.webmanifest"><script id="vite-plugin-pwa:register-sw" src="/registerSW.js"></script></head>
  <body>
    <script>
      window.addEventListener('error', function(e) {
        document.body.innerHTML = '<div style="padding: 20px; background: white; color: red; font-family: monospace; word-wrap: break-word;"><b>FATAL ERROR:</b> ' + e.message + '<br>' + e.filename + ':' + e.lineno + '<br><br>Please send a screenshot of this.</div>';
      });
      window.addEventListener('unhandledrejection', function(e) {
        document.body.innerHTML = '<div style="padding: 20px; background: white; color: red; font-family: monospace; word-wrap: break-word;"><b>PROMISE ERROR:</b> ' + (e.reason && e.reason.message ? e.reason.message : e.reason) + '<br><br>Please send a screenshot of this.</div>';
      });
    </script>
    <div id="root"></div>
    <script>
      if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(function(registrations) {
          for(let registration of registrations) {
            registration.unregister();
          }
        });
      }
    </script>
  </body>
